package main

import (
	"embed"
	"fmt"
	"io/fs"
	"net/http"
	"os"
	"path"
	"strings"
)

// webBundle holds the production frontend build. It is generated by
// `npm run build` in ../../frontend (Vite outDir) and committed, so a plain
// `go build` produces a self-contained binary without Node/npm installed.
//
//go:embed all:web
var webBundle embed.FS

// frontendFS returns the filesystem to serve the frontend from: dir when set,
// otherwise the embedded bundle.
func frontendFS(dir string) (fs.FS, error) {
	if dir != "" {
		if _, err := os.Stat(path.Join(dir, "index.html")); err != nil {
			return nil, fmt.Errorf("-web-dir %q has no index.html: %w", dir, err)
		}
		return os.DirFS(dir), nil
	}
	return fs.Sub(webBundle, "web")
}

// spaHandler serves real files from site directly and falls back to
// index.html for every other path so client-side routing works.
func spaHandler(site fs.FS) http.Handler {
	files := http.FileServer(http.FS(site))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(path.Clean(r.URL.Path), "/")
		if name != "" {
			if fi, err := fs.Stat(site, name); err == nil && !fi.IsDir() {
				files.ServeHTTP(w, r)
				return
			}
		}
		http.ServeFileFS(w, r, site, "index.html")
	})
}
